class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        best = list(nums)
        ans = sum(best)
        for k in range(1, n):
            total = 0
            for i in range(n):
                v = nums[(i - k) % n]
                if v < best[i]:
                    best[i] = v
                total += best[i]
            ans = min(ans, total + k * x)
        return ans
